package com.coffeeshop.service;import com.coffeeshop.dto.ExpenseCommands;import com.coffeeshop.model.ExpenseModels;import com.coffeeshop.repository.ExpenseRepository;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class ExpenseServiceTest{private final Stub repo=new Stub();private final ExpenseService service=new ExpenseService(repo);@Test void validatesCategory(){service.saveCategory(new ExpenseCommands.Category(null," RENT "," Rent ",true,null));assertEquals("RENT",repo.category.code());assertThrows(IllegalArgumentException.class,()->service.saveCategory(new ExpenseCommands.Category(1L,"A","B",true,null)));}@Test void validatesAndRoundsExpense(){service.saveExpense(new ExpenseCommands.Expense(null,1,LocalDateTime.now(),new BigDecimal("12.34567")," Office ",null,null,null),7);assertEquals(new BigDecimal("12.3457"),repo.expense.amount());assertEquals("Office",repo.expense.description());}@Test void rejectsInvalidExpense(){assertThrows(IllegalArgumentException.class,()->service.saveExpense(new ExpenseCommands.Expense(null,0,LocalDateTime.now(),BigDecimal.ONE,null,null,null,null),7));assertThrows(IllegalArgumentException.class,()->service.saveExpense(new ExpenseCommands.Expense(null,1,LocalDateTime.now(),BigDecimal.ZERO,null,null,null,null),7));}@Test void editRequiresVersion(){assertThrows(IllegalArgumentException.class,()->service.saveExpense(new ExpenseCommands.Expense(1L,1,LocalDateTime.now(),BigDecimal.ONE,null,null,null,null),7));}private static final class Stub implements ExpenseRepository{ExpenseCommands.Category category;ExpenseCommands.Expense expense;public ExpenseModels.Catalog load(){return new ExpenseModels.Catalog(List.of(),List.of());}public long saveCategory(ExpenseCommands.Category q){category=q;return 1;}public void setCategoryActive(long id,boolean a,byte[]v){}public long saveExpense(ExpenseCommands.Expense q,long u){expense=q;return 1;}}}
